<script setup lang="ts">const route=useRoute(),{lang}=useLocale(); const {data:service,error}=await useFetch<any>(`/api/catalog/services/${route.params.code}`); if(error.value) throw createError({statusCode:404}); const {data:countries}=await useFetch<any[]>('/api/catalog/countries'); const name=computed(()=>lang.value==='ru'?service.value?.nameRu:service.value?.nameEn); usePageSeo(computed(()=>`${name.value}: ${lang.value==='ru'?'номера для SMS':'SMS numbers'}`),computed(()=>lang.value==='ru'?`Выберите страну и просмотрите публичные номера для ${name.value}.`:`Choose a country and browse public numbers for ${name.value}.`))</script>
<template><div class="shell page"><div class="country-title"><img class="service-hero-icon" :src="`/images/services/${service.code}.webp`"><div><span class="kicker">Service / {{service.code.toUpperCase()}}</span><h1>{{name}}</h1></div></div><p class="lead">{{lang==='ru'?`Выберите страну для просмотра публичных номеров, связанных с ${name}. Доступность кодов зависит от внешнего отправителя, а содержимое демонстрационной ленты не является реальной доставкой.`:`Choose a country to browse public numbers associated with ${name}. Code availability depends on the external sender, and the simulated feed is not real message delivery.`}}</p><div class="card-grid"><CountryCard v-for="c in countries?.slice(0,24)" :key="c.id" :country="c"/></div><PremiumBanner medium="premium_card"/><SeoCopy :subject="name" type="service"/></div></template>
